import{_ as e,o,c as a,a2 as d}from"./chunks/framework.Bx7X8BVG.js";const p=JSON.parse('{"title":"安全与公网暴露","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1790778157000}'),r={name:"guide/security.md"};function l(c,t,n,s,i,h){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="安全与公网暴露" tabindex="-1">安全与公网暴露 <a class="header-anchor" href="#安全与公网暴露" aria-label="Permalink to &quot;安全与公网暴露&quot;">​</a></h1><p>这个面板能创建隧道和 DNS 记录，<strong>等于你内网的入口</strong>。它默认面向内网使用，放到公网前请按本文做一遍。</p><h2 id="默认状态与风险" tabindex="-1">默认状态与风险 <a class="header-anchor" href="#默认状态与风险" aria-label="Permalink to &quot;默认状态与风险&quot;">​</a></h2><p>下表以 Docker 默认部署为准。桌面 v1.8.1 只监听本机 <code>127.0.0.1</code>，端口动态选择。详见 <a href="/cloudflare-tunnel-manager/guide/desktop#端口和数据目录">桌面数据与端口</a>。</p><table tabindex="0"><thead><tr><th>项目</th><th>默认</th><th>风险</th></tr></thead><tbody><tr><td>面板登录</td><td><strong>首次启动引导注册管理员</strong>，之后需登录</td><td>未设 <code>ADMIN_PASSWORD</code> 时紧急通道关闭，属正常</td></tr><tr><td>开放注册</td><td>开启（但新用户需审核）</td><td>陌生人可提交注册申请，别乱点通过</td></tr><tr><td>端口 19092 / 19093</td><td>监听所有网卡</td><td><strong>API Key 泄露即可完全操控隧道与 DNS</strong></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">不要把 19092 / 19093 暴露到公网</p><p>这两个端口是给内网程序调用的。它们只能靠一个 Key 保护，且没有登录限速。用防火墙限制来源，或只在 VPN / 局域网内访问。</p></div><h2 id="公网暴露面板时" tabindex="-1">公网暴露面板时 <a class="header-anchor" href="#公网暴露面板时" aria-label="Permalink to &quot;公网暴露面板时&quot;">​</a></h2><p>建议按顺序做这几件事：</p><h3 id="_1-走-cloudflare-access-最推荐" tabindex="-1">1. 走 Cloudflare Access（最推荐） <a class="header-anchor" href="#_1-走-cloudflare-access-最推荐" aria-label="Permalink to &quot;1. 走 Cloudflare Access（最推荐）&quot;">​</a></h3><p>在 Cloudflare Zero Trust 里给面板域名配一条 Access 策略（例如只允许你自己的邮箱），<strong>访问前先过 Cloudflare 身份验证</strong>。这样即便域名被扫描到，没有授权也进不来。这是比任何面板自带功能都强的防线。</p><h3 id="_2-改站点名称与关掉开放注册" tabindex="-1">2. 改站点名称与关掉开放注册 <a class="header-anchor" href="#_2-改站点名称与关掉开放注册" aria-label="Permalink to &quot;2. 改站点名称与关掉开放注册&quot;">​</a></h3><ul><li>「系统配置 → 站点设置 → 站点名称」改成<strong>不含业务特征</strong>的名字，别用 <code>panel</code>、<code>tunnel</code>、<code>nas</code> 这类可被关键词命中的词</li><li>「用户管理 → 注册开关」<strong>关闭</strong>，禁止陌生人提交注册</li></ul><h3 id="_3-域名本身别太好猜" tabindex="-1">3. 域名本身别太好猜 <a class="header-anchor" href="#_3-域名本身别太好猜" aria-label="Permalink to &quot;3. 域名本身别太好猜&quot;">​</a></h3><p><code>panel.xxx.com</code>、<code>tunnel.xxx.com</code> 是扫描器的字典常客。用无规律的子域名能减少被批量扫描命中的概率。</p><h3 id="_4-强密码-定期轮换-api-凭证" tabindex="-1">4. 强密码 + 定期轮换 API 凭证 <a class="header-anchor" href="#_4-强密码-定期轮换-api-凭证" aria-label="Permalink to &quot;4. 强密码 + 定期轮换 API 凭证&quot;">​</a></h3><p>管理员密码不要复用，API 凭证定期删除重建。</p><h2 id="三层反收录" tabindex="-1">三层反收录 <a class="header-anchor" href="#三层反收录" aria-label="Permalink to &quot;三层反收录&quot;">​</a></h2><p>「站点设置」里的「<strong>禁止搜索引擎收录</strong>」默认开启（<strong>建议保持开启</strong>），它会同时上三道拦截：</p><table tabindex="0"><thead><tr><th>层次</th><th>内容</th><th>特点</th></tr></thead><tbody><tr><td><code>GET /robots.txt</code></td><td><code>User-agent: *</code> + <code>Disallow: /</code></td><td>全站禁止抓取，守规矩的爬虫会直接离开</td></tr><tr><td><code>X-Robots-Tag</code> 响应头</td><td><code>noindex, nofollow, noarchive, nosnippet, noimageindex, notranslate</code></td><td>向爬虫声明不要索引或留快照；不能强制不守规则的爬虫遵守</td></tr><tr><td>页面 <code>&lt;meta name=&quot;robots&quot;&gt;</code></td><td>同样的 noindex 声明，另附 <code>referrer: no-referrer</code></td><td>从本页面点外链时不泄露来源地址</td></tr></tbody></table><p>关掉这个开关后，<code>robots.txt</code> 会降级为只禁 <code>/api/</code>，响应头也不再发送。</p><div class="warning custom-block"><p class="custom-block-title">降低曝光 ≠ 访问控制</p><p>这三层只能<strong>减少被搜索引擎和批量扫描器发现的机会</strong>，挡不住已经知道你地址的人。真正防入侵请用 Cloudflare Access 或强密码。</p><p>另外：搜索引擎基本不会收录「没有任何外链指向」的地址。所以<strong>不要在论坛、群聊、公开截图里贴出面板链接</strong>，这一条比改名字更关键。</p></div><h2 id="凭据是怎么存的" tabindex="-1">凭据是怎么存的 <a class="header-anchor" href="#凭据是怎么存的" aria-label="Permalink to &quot;凭据是怎么存的&quot;">​</a></h2><p>桌面版数据在用户应用目录的 <code>data/</code>，Docker 默认在宿主机项目 <code>data/</code>。Cloudflare Token 当前保存在 <code>config.json</code>，不是系统密钥链加密存储；备份含敏感凭据，请限制访问并加密保存。调用 Cloudflare API 时会发送相应凭据和配置，业务流量经 Tunnel 经过 Cloudflare，不能宣传为所有数据永远不离开本机。</p><ul><li>Cloudflare API Token 只保存在<strong>你自己的 <code>/data</code> 目录</strong>（<code>config.json</code>）</li><li>用户密码用 <strong>scrypt 加盐哈希</strong>存储，不存明文</li><li>会话 Cookie 设了 <code>HttpOnly</code> + <code>SameSite=Strict</code>，有效期 7 天</li><li>项目不设置独立的遥测上报服务；管理 Cloudflare 隧道/DNS 的 API 请求仍会将相应凭据和配置发送给 Cloudflare，Git/npm/镜像下载也会访问配置的外部下载源。</li></ul><h2 id="如果凭据泄露了" tabindex="-1">如果凭据泄露了 <a class="header-anchor" href="#如果凭据泄露了" aria-label="Permalink to &quot;如果凭据泄露了&quot;">​</a></h2><ol><li>立刻去 Cloudflare 后台<strong>删除那个 API Token</strong>（新建一个填回面板）</li><li>在「API 凭证」页删除所有可疑凭证</li><li>检查隧道列表里的<strong>转发规则有没有被改成陌生域名</strong></li><li>检查 DNS 记录有没有被添加未知的 CNAME</li></ol><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>该做什么</th></tr></thead><tbody><tr><td>只在内网用</td><td>保持默认即可，别把端口映射出去</td></tr><tr><td>想在外网访问面板</td><td>上 Cloudflare Access + 关开放注册 + 改站点名</td></tr><tr><td>只用隧道服务本身</td><td>面板端口别对公网开放，只开隧道用的域名</td></tr></tbody></table>',28)])])}const b=e(r,[["render",l]]);export{p as __pageData,b as default};
